package com.learnagent.memory;

import com.fasterxml.jackson.core.type.TypeReference;import com.fasterxml.jackson.databind.ObjectMapper;import com.learnagent.quiz.*;import java.time.*;import java.util.*;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;
@Service public class KnowledgeGraphService{private final KnowledgeNodeRepository nodes;private final KnowledgeEdgeRepository edges;private final FlashcardRepository cards;private final FlashcardReviewStateRepository states;private final AnswerRecordRepository answers;private final FsrsSchedulerService fsrs;private final ObjectMapper json;public KnowledgeGraphService(KnowledgeNodeRepository nodes,KnowledgeEdgeRepository edges,FlashcardRepository cards,FlashcardReviewStateRepository states,AnswerRecordRepository answers,FsrsSchedulerService fsrs,ObjectMapper json){this.nodes=nodes;this.edges=edges;this.cards=cards;this.states=states;this.answers=answers;this.fsrs=fsrs;this.json=json;}@Transactional public KnowledgeNode ensureNode(UUID courseId,String name,String sources){String key=normalize(name);return nodes.findByCourseIdAndNormalizedKey(courseId,key).orElseGet(()->nodes.save(new KnowledgeNode(courseId,name.trim(),key,sources)));}@Transactional public void addEdge(UUID courseId,String from,String to,KnowledgeRelation relation,String sources){if(from==null||to==null||from.isBlank()||to.isBlank()||from.equalsIgnoreCase(to)||emptySources(sources))return;KnowledgeNode source=ensureNode(courseId,from,sources),target=ensureNode(courseId,to,sources);if(!edges.existsByCourseIdAndFromNodeIdAndToNodeIdAndRelation(courseId,source.getId(),target.getId(),relation))edges.save(new KnowledgeEdge(courseId,source.getId(),target.getId(),relation,sources));}@Transactional public void refresh(UUID courseId,String point){KnowledgeNode node=ensureNode(courseId,point,"[]");List<AnswerRecord>records=answers.findByCourseId(courseId).stream().filter(value->point.equalsIgnoreCase(value.getKnowledgePoint())).toList();double mastery=records.isEmpty()?0:(double)records.stream().filter(AnswerRecord::isCorrect).count()/records.size();List<Flashcard>active=cards.findByCourseIdAndKnowledgePointIgnoreCaseAndStatus(courseId,point,FlashcardStatus.ACTIVE);double retrieval=active.stream().map(Flashcard::getId).map(states::findById).flatMap(Optional::stream).mapToDouble(value->{double current=fsrs.retrievability(value.getFsrsCardJson(),Instant.now());value.refreshRetrievability(current);return current;}).average().orElse(1);String sources=active.stream().map(Flashcard::getSourceJson).filter(value->!emptySources(value)).findFirst().orElse(node.getSourceJson());node.update(mastery,retrieval,sources);}@Transactional(readOnly=true)public MemoryDtos.GraphView graph(UUID courseId){List<MemoryDtos.NodeView>nodeViews=nodes.findByCourseIdOrderByName(courseId).stream().map(this::view).toList();List<MemoryDtos.EdgeView>edgeViews=edges.findByCourseId(courseId).stream().map(value->new MemoryDtos.EdgeView(value.getId(),value.getFromNodeId(),value.getToNodeId(),value.getRelation(),sources(value.getSourceJson()))).toList();return new MemoryDtos.GraphView(nodeViews,edgeViews);}@Transactional(readOnly=true)public List<MemoryDtos.NodeView>highRisk(int limit){return nodes.findAll().stream().sorted(Comparator.comparingDouble(KnowledgeNode::getForgettingRisk).reversed()).limit(limit).map(this::view).toList();}private MemoryDtos.NodeView view(KnowledgeNode value){return new MemoryDtos.NodeView(value.getId(),value.getCourseId(),value.getName(),value.getMastery(),value.getRetrievability(),value.getForgettingRisk(),sources(value.getSourceJson()));}private List<MemoryDtos.SourceRef>sources(String value){if(emptySources(value))return List.of();try{return json.readValue(value,new TypeReference<>(){});}catch(Exception ignored){return List.of();}}private boolean emptySources(String value){return value==null||value.isBlank()||"[]".equals(value.trim());}private String normalize(String value){return value==null?"unknown":value.trim().toLowerCase(Locale.ROOT).replaceAll("\\s+"," ");}}
